-- Real exchange rates (shared, all companies): Federal Reserve G.5 monthly averages 2019-01 .. 2026-09
-- for EUR, GBP, INR, CNY, JPY, CHF, AUD, CAD, SGD (units per US dollar), the annual averages of the
-- complete years, and the 2025 US CPI-U annual average (BLS: 321.943, October 2025 not collected).
-- Data files: data/fx/. Demo rates are removed.
SELECT set_config('app.platform', 'on', true);
DELETE FROM fx_rate WHERE source LIKE 'DEMO rate%';
ON CONFLICT (coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid), currency, kind, period) DO UPDATE SET per_usd = EXCLUDED.per_usd, source = EXCLUDED.source;
ON CONFLICT DO NOTHING;
